<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Services\PosService;use App\Services\PosSyncService;use Illuminate\Http\Request;
class PosSyncController extends Controller{public function store(Request $r,PosSyncService $sync,PosService $pos){$d=$r->validate(['batch_uuid'=>'required|uuid','device_id'=>'required|string|max:100','sales'=>'required|array|max:100','sales.*.client_uuid'=>'required|uuid|distinct','sales.*.inventory_location_id'=>'required|exists:inventory_locations,id','sales.*.payment_method'=>'required|in:cash,card,bkash,nagad','sales.*.paid_amount'=>'required|numeric|min:0','sales.*.discount_total'=>'nullable|numeric|min:0','sales.*.items'=>'required|array|min:1','sales.*.items.*.variant_id'=>'required|exists:product_variants,id','sales.*.items.*.quantity'=>'required|numeric|min:0.01']);return response()->json($sync->sync($d,$r->user()->id,$pos));}}
